package com.intellisoft.androidcuisine.data.managers

import android.content.Context
import android.content.SharedPreferences
import android.util.Log
import com.google.firebase.messaging.FirebaseMessaging
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlin.coroutines.resume
import kotlin.coroutines.resumeWithException

/**
 * Manager para manejar el token de FCM
 */
class FCMTokenManager(private val context: Context) {

    companion object {
        private const val TAG = "FCMTokenManager"
        private const val PREFS_NAME = "fcm_prefs"
        private const val KEY_FCM_TOKEN = "fcm_token"
        private const val KEY_TOKEN_TIMESTAMP = "token_timestamp"
        private const val TOKEN_VALIDITY_DURATION = 24 * 60 * 60 * 1000L // 24 horas en milisegundos
    }

    private val sharedPrefs: SharedPreferences = 
        context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)

    /**
     * Obtiene el token FCM actual de Firebase
     */
    suspend fun getFCMToken(): String? = suspendCancellableCoroutine { continuation ->
        FirebaseMessaging.getInstance().token
            .addOnCompleteListener { task ->
                if (!task.isSuccessful) {
                    Log.w(TAG, "Error al obtener FCM token", task.exception)
                    continuation.resumeWithException(
                        task.exception ?: Exception("Error desconocido al obtener token")
                    )
                    return@addOnCompleteListener
                }

                val token = task.result
                Log.d(TAG, "FCM Token obtenido: $token")

                // Guardar el token localmente
                saveTokenToPreferences(token)

                continuation.resume(token)
            }
    }

    /**
     * Obtiene el token guardado en SharedPreferences
     */
    fun getSavedToken(): String? {
        return sharedPrefs.getString(KEY_FCM_TOKEN, null)
    }

    /**
     * Verifica si el token guardado es válido (no ha expirado)
     */
    fun isTokenValid(): Boolean {
        val savedToken = getSavedToken()
        if (savedToken.isNullOrEmpty()) return false

        val timestamp = sharedPrefs.getLong(KEY_TOKEN_TIMESTAMP, 0)
        val currentTime = System.currentTimeMillis()

        return (currentTime - timestamp) < TOKEN_VALIDITY_DURATION
    }

    /**
     * Guarda el token en SharedPreferences
     */
    fun saveTokenToPreferences(token: String) {
        with(sharedPrefs.edit()) {
            putString(KEY_FCM_TOKEN, token)
            putLong(KEY_TOKEN_TIMESTAMP, System.currentTimeMillis())
            apply()
        }
        Log.d(TAG, "Token guardado en preferencias: $token")
    }

    /**
     * Elimina el token guardado
     */
    fun clearToken() {
        with(sharedPrefs.edit()) {
            remove(KEY_FCM_TOKEN)
            remove(KEY_TOKEN_TIMESTAMP)
            apply()
        }
        Log.d(TAG, "Token eliminado de preferencias")
    }

    /**
     * Fuerza la obtención de un nuevo token
     */
    suspend fun refreshToken(): String? {
        return try {
            // Primero eliminamos el token actual
            FirebaseMessaging.getInstance().deleteToken()

            // Luego obtenemos uno nuevo
            getFCMToken()
        } catch (e: Exception) {
            Log.e(TAG, "Error al refrescar token", e)
            null
        }
    }

    /**
     * Suscribirse a un topic de FCM
     */
    fun subscribeToTopic(topic: String, callback: (Boolean) -> Unit) {
        FirebaseMessaging.getInstance().subscribeToTopic(topic)
            .addOnCompleteListener { task ->
                val success = task.isSuccessful
                if (success) {
                    Log.d(TAG, "Suscrito al topic: $topic")
                } else {
                    Log.w(TAG, "Error al suscribirse al topic: $topic", task.exception)
                }
                callback(success)
            }
    }

    /**
     * Desuscribirse de un topic de FCM
     */
    fun unsubscribeFromTopic(topic: String, callback: (Boolean) -> Unit) {
        FirebaseMessaging.getInstance().unsubscribeFromTopic(topic)
            .addOnCompleteListener { task ->
                val success = task.isSuccessful
                if (success) {
                    Log.d(TAG, "Desuscrito del topic: $topic")
                } else {
                    Log.w(TAG, "Error al desuscribirse del topic: $topic", task.exception)
                }
                callback(success)
            }
    }

    /**
     * Verifica si las notificaciones están habilitadas
     */
    fun areNotificationsEnabled(): Boolean {
        return try {
            val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) 
                as android.app.NotificationManager
            notificationManager.areNotificationsEnabled()
        } catch (e: Exception) {
            Log.e(TAG, "Error al verificar notificaciones", e)
            false
        }
    }
}

package com.intellisoft.androidcuisine.data.managers

import android.content.Context
import android.content.SharedPreferences
import android.util.Log
import com.google.gson.Gson
import com.intellisoft.androidcuisine.data.remote.dto.LoginResponse
import com.intellisoft.androidcuisine.data.remote.dto.Modulo

class SessionManager(context: Context) {

    companion object {
        private const val PREF_NAME = "user_session"
        private const val KEY_ACCESS_TOKEN = "access_token"
        private const val KEY_TOKEN_TYPE = "token_type"
        private const val KEY_EXPIRES_IN = "expires_in"
        private const val KEY_USER_ID = "user_id"
        private const val KEY_USER_NAME = "user_name"
        private const val KEY_USER_EMAIL = "user_email"
        private const val KEY_USER_APELLIDO = "user_apellido"
        private const val KEY_USER_TELEFONO = "user_telefono"
        private const val KEY_IS_ADMIN = "is_admin"
        private const val KEY_ES_CLIENTE = "es_cliente"
        private const val KEY_ACEPTA_MARKETING = "acepta_marketing"
        private const val KEY_MOSTRAR_EMPRESAS = "mostrar_empresas"
        private const val KEY_TIPO_ACCESO = "tipo_acceso"
        private const val KEY_USER_MODULES = "user_modules"
        private const val KEY_LOGIN_TIME = "login_time"

        @Volatile
        private var INSTANCE: SessionManager? = null

        fun getInstance(context: Context): SessionManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: SessionManager(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    private val sharedPreferences: SharedPreferences = context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)
    private val gson = Gson()

    /**
     * Guarda toda la información de login
     */
    fun saveLoginData(loginResponse: LoginResponse) {
        val editor = sharedPreferences.edit()

        // Token info
        editor.putString(KEY_ACCESS_TOKEN, loginResponse.access_token)
        editor.putString(KEY_TOKEN_TYPE, loginResponse.token_type)
        editor.putInt(KEY_EXPIRES_IN, loginResponse.expires_in)
        editor.putLong(KEY_LOGIN_TIME, System.currentTimeMillis())

        // User info
        val user = loginResponse.user
        editor.putInt(KEY_USER_ID, user.id)
        editor.putString(KEY_USER_NAME, user.nombre)
        editor.putString(KEY_USER_EMAIL, user.email)
        editor.putString(KEY_USER_APELLIDO, user.apellido)
        editor.putString(KEY_USER_TELEFONO, user.telefono)
        editor.putBoolean(KEY_IS_ADMIN, user.es_admin)
        editor.putBoolean(KEY_ES_CLIENTE, user.es_cliente)
        editor.putBoolean(KEY_ACEPTA_MARKETING, user.acepta_marketing)
        editor.putBoolean(KEY_MOSTRAR_EMPRESAS, user.mostrar_empresas)
        editor.putString(KEY_TIPO_ACCESO, user.tipo_acceso)

        // Modules as JSON
        val modulesJson = gson.toJson(user.modulos)
        editor.putString(KEY_USER_MODULES, modulesJson)

        editor.apply()

        Log.d("SessionManager", "✅ Datos de sesión guardados")
        Log.d("SessionManager", "Usuario: ${user.nombre}")
        Log.d("SessionManager", "Token: ${loginResponse.access_token.take(20)}...")
        Log.d("SessionManager", "Módulos: ${user.modulos.size}")
    }

    /**
     * Obtiene el token Bearer completo para Authorization header
     */
    fun getBearerToken(): String? {
        val tokenType = sharedPreferences.getString(KEY_TOKEN_TYPE, "Bearer") ?: "Bearer"
        val accessToken = sharedPreferences.getString(KEY_ACCESS_TOKEN, null)

        return if (accessToken != null) {
            "$tokenType $accessToken"
        } else {
            null
        }
    }

    /**
     * Obtiene solo el access token
     */
    fun getAccessToken(): String? {
        return sharedPreferences.getString(KEY_ACCESS_TOKEN, null)
    }

    /**
     * Verifica si hay una sesión activa
     */
    fun isLoggedIn(): Boolean {
        val token = getAccessToken()
        return !token.isNullOrEmpty() && !isTokenExpired()
    }

    /**
     * Verifica si el token ha expirado
     */
    fun isTokenExpired(): Boolean {
        val loginTime = sharedPreferences.getLong(KEY_LOGIN_TIME, 0)
        val expiresIn = sharedPreferences.getInt(KEY_EXPIRES_IN, 0)

        if (loginTime == 0L || expiresIn == 0) {
            return true
        }

        val currentTime = System.currentTimeMillis()
        val expirationTime = loginTime + (expiresIn * 1000L) // expiresIn está en segundos

        return currentTime >= expirationTime
    }

    /**
     * Obtiene datos del usuario
     */
    fun getUserData(): UserData? {
        if (!isLoggedIn()) return null

        return UserData(
            id = sharedPreferences.getInt(KEY_USER_ID, 0),
            nombre = sharedPreferences.getString(KEY_USER_NAME, "") ?: "",
            email = sharedPreferences.getString(KEY_USER_EMAIL, "") ?: "",
            apellido = sharedPreferences.getString(KEY_USER_APELLIDO, "") ?: "",
            telefono = sharedPreferences.getString(KEY_USER_TELEFONO, "") ?: "",
            esAdmin = sharedPreferences.getBoolean(KEY_IS_ADMIN, false),
            esCliente = sharedPreferences.getBoolean(KEY_ES_CLIENTE, false),
            aceptaMarketing = sharedPreferences.getBoolean(KEY_ACEPTA_MARKETING, false),
            mostrarEmpresas = sharedPreferences.getBoolean(KEY_MOSTRAR_EMPRESAS, false),
            tipoAcceso = sharedPreferences.getString(KEY_TIPO_ACCESO, "") ?: ""
        )
    }

    /**
     * Obtiene módulos del usuario
     */
    fun getUserModules(): List<Modulo> {
        val modulesJson = sharedPreferences.getString(KEY_USER_MODULES, "[]") ?: "[]"
        return try {
            val type = object : com.google.gson.reflect.TypeToken<List<Modulo>>() {}.type
            gson.fromJson(modulesJson, type) ?: emptyList()
        } catch (e: Exception) {
            Log.e("SessionManager", "Error parseando módulos: ${e.message}")
            emptyList()
        }
    }

    /**
     * Limpia toda la sesión
     */
    fun clearSession() {
        sharedPreferences.edit().clear().apply()
        Log.d("SessionManager", " Sesión limpiada")
    }

    /**
     * Actualiza solo el token (para refresh token)
     */
    fun updateToken(newToken: String, expiresIn: Int) {
        val editor = sharedPreferences.edit()
        editor.putString(KEY_ACCESS_TOKEN, newToken)
        editor.putInt(KEY_EXPIRES_IN, expiresIn)
        editor.putLong(KEY_LOGIN_TIME, System.currentTimeMillis())
        editor.apply()

        Log.d("SessionManager", " Token actualizado")
    }
}

/**
 * Clase de datos para información del usuario
 */
data class UserData(
    val id: Int,
    val nombre: String,
    val email: String,
    val apellido: String,
    val telefono: String,
    val esAdmin: Boolean,
    val esCliente: Boolean,
    val aceptaMarketing: Boolean,
    val mostrarEmpresas: Boolean,
    val tipoAcceso: String
)

package com.intellisoft.androidcuisine.data.managers

import android.content.Context
import android.content.SharedPreferences
import android.util.Log
import com.google.gson.Gson
import com.intellisoft.androidcuisine.data.remote.dto.LoginResponse
import com.intellisoft.androidcuisine.data.remote.dto.Modulo

class SessionManager(context: Context) {

    companion object {
        private const val PREF_NAME = "user_session"
        private const val KEY_ACCESS_TOKEN = "access_token"
        private const val KEY_TOKEN_TYPE = "token_type"
        private const val KEY_EXPIRES_IN = "expires_in"
        private const val KEY_USER_ID = "user_id"
        private const val KEY_USER_NAME = "user_name"
        private const val KEY_USER_EMAIL = "user_email"
        private const val KEY_USER_APELLIDO = "user_apellido"
        private const val KEY_USER_TELEFONO = "user_telefono"
        private const val KEY_IS_ADMIN = "is_admin"
        private const val KEY_ES_CLIENTE = "es_cliente"
        private const val KEY_ACEPTA_MARKETING = "acepta_marketing"
        private const val KEY_MOSTRAR_EMPRESAS = "mostrar_empresas"
        private const val KEY_TIPO_ACCESO = "tipo_acceso"
        private const val KEY_USER_MODULES = "user_modules"
        private const val KEY_LOGIN_TIME = "login_time"

        @Volatile
        private var INSTANCE: SessionManager? = null

        fun getInstance(context: Context): SessionManager {
            return INSTANCE ?: synchronized(this) {
                INSTANCE ?: SessionManager(context.applicationContext).also { INSTANCE = it }
            }
        }
    }

    private val sharedPreferences: SharedPreferences = context.getSharedPreferences(PREF_NAME, Context.MODE_PRIVATE)
    private val gson = Gson()

    /**
     * Guarda toda la información de login
     */
    fun saveLoginData(loginResponse: LoginResponse) {
        val editor = sharedPreferences.edit()

        // Token info
        editor.putString(KEY_ACCESS_TOKEN, loginResponse.access_token)
        editor.putString(KEY_TOKEN_TYPE, loginResponse.token_type)
        editor.putInt(KEY_EXPIRES_IN, loginResponse.expires_in)
        editor.putLong(KEY_LOGIN_TIME, System.currentTimeMillis())

        // User info
        val user = loginResponse.user
        editor.putInt(KEY_USER_ID, user.id)
        editor.putString(KEY_USER_NAME, user.nombre)
        editor.putString(KEY_USER_EMAIL, user.email)
        editor.putString(KEY_USER_APELLIDO, user.apellido)
        editor.putString(KEY_USER_TELEFONO, user.telefono)
        editor.putBoolean(KEY_IS_ADMIN, user.es_admin)
        editor.putBoolean(KEY_ES_CLIENTE, user.es_cliente)
        editor.putBoolean(KEY_ACEPTA_MARKETING, user.acepta_marketing)
        editor.putBoolean(KEY_MOSTRAR_EMPRESAS, user.mostrar_empresas)
        editor.putString(KEY_TIPO_ACCESO, user.tipo_acceso)

        // Modules as JSON
        val modulesJson = gson.toJson(user.modulos)
        editor.putString(KEY_USER_MODULES, modulesJson)

        editor.apply()

        Log.d("SessionManager", "✅ Datos de sesión guardados")
        Log.d("SessionManager", "Usuario: ${user.nombre}")
        Log.d("SessionManager", "Token: ${loginResponse.access_token.take(20)}...")
        Log.d("SessionManager", "Módulos: ${user.modulos.size}")
    }

    /**
     * Obtiene el token Bearer completo para Authorization header
     */
    fun getBearerToken(): String? {
        val tokenType = sharedPreferences.getString(KEY_TOKEN_TYPE, "Bearer") ?: "Bearer"
        val accessToken = sharedPreferences.getString(KEY_ACCESS_TOKEN, null)

        return if (accessToken != null) {
            "$tokenType $accessToken"
        } else {
            null
        }
    }

    /**
     * Obtiene solo el access token
     */
    fun getAccessToken(): String? {
        return sharedPreferences.getString(KEY_ACCESS_TOKEN, null)
    }

    /**
     * Verifica si hay una sesión activa
     */
    fun isLoggedIn(): Boolean {
        val token = getAccessToken()
        return !token.isNullOrEmpty() && !isTokenExpired()
    }

    /**
     * Verifica si el token ha expirado
     */
    fun isTokenExpired(): Boolean {
        val loginTime = sharedPreferences.getLong(KEY_LOGIN_TIME, 0)
        val expiresIn = sharedPreferences.getInt(KEY_EXPIRES_IN, 0)

        if (loginTime == 0L || expiresIn == 0) {
            return true
        }

        val currentTime = System.currentTimeMillis()
        val expirationTime = loginTime + (expiresIn * 1000L) // expiresIn está en segundos

        return currentTime >= expirationTime
    }

    /**
     * Obtiene datos del usuario
     */
    fun getUserData(): UserData? {
        if (!isLoggedIn()) return null

        return UserData(
            id = sharedPreferences.getInt(KEY_USER_ID, 0),
            nombre = sharedPreferences.getString(KEY_USER_NAME, "") ?: "",
            email = sharedPreferences.getString(KEY_USER_EMAIL, "") ?: "",
            apellido = sharedPreferences.getString(KEY_USER_APELLIDO, "") ?: "",
            telefono = sharedPreferences.getString(KEY_USER_TELEFONO, "") ?: "",
            esAdmin = sharedPreferences.getBoolean(KEY_IS_ADMIN, false),
            esCliente = sharedPreferences.getBoolean(KEY_ES_CLIENTE, false),
            aceptaMarketing = sharedPreferences.getBoolean(KEY_ACEPTA_MARKETING, false),
            mostrarEmpresas = sharedPreferences.getBoolean(KEY_MOSTRAR_EMPRESAS, false),
            tipoAcceso = sharedPreferences.getString(KEY_TIPO_ACCESO, "") ?: ""
        )
    }

    /**
     * Obtiene módulos del usuario
     */
    fun getUserModules(): List<Modulo> {
        val modulesJson = sharedPreferences.getString(KEY_USER_MODULES, "[]") ?: "[]"
        return try {
            val type = object : com.google.gson.reflect.TypeToken<List<Modulo>>() {}.type
            gson.fromJson(modulesJson, type) ?: emptyList()
        } catch (e: Exception) {
            Log.e("SessionManager", "Error parseando módulos: ${e.message}")
            emptyList()
        }
    }

    /**
     * Limpia toda la sesión
     */
    fun clearSession() {
        sharedPreferences.edit().clear().apply()
        Log.d("SessionManager", " Sesión limpiada")
    }

    /**
     * Actualiza solo el token (para refresh token)
     */
    fun updateToken(newToken: String, expiresIn: Int) {
        val editor = sharedPreferences.edit()
        editor.putString(KEY_ACCESS_TOKEN, newToken)
        editor.putInt(KEY_EXPIRES_IN, expiresIn)
        editor.putLong(KEY_LOGIN_TIME, System.currentTimeMillis())
        editor.apply()

        Log.d("SessionManager", " Token actualizado")
    }

    /**
     * Obtiene el ID del usuario almacenado en la sesión
     */
    fun getUserId(): Int {
        return sharedPreferences.getInt(KEY_USER_ID, -1)
    }
}

/**
 * Clase de datos para información del usuario
 */
data class UserData(
    val id: Int,
    val nombre: String,
    val email: String,
    val apellido: String,
    val telefono: String,
    val esAdmin: Boolean,
    val esCliente: Boolean,
    val aceptaMarketing: Boolean,
    val mostrarEmpresas: Boolean,
    val tipoAcceso: String
)

package com.intellisoft.androidcuisine.data.repository

import android.util.Log
import com.intellisoft.androidcuisine.data.managers.FCMTokenManager
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * Repositorio para manejar operaciones relacionadas con FCM
 */
class FCMRepository(
    private val fcmTokenManager: FCMTokenManager
) {

    companion object {
        private const val TAG = "FCMRepository"
    }

    /**
     * Registra el token FCM en el servidor
     */
    suspend fun registerTokenWithServer(
        userId: String? = null,
        deviceInfo: Map<String, String> = emptyMap()
    ): Result<Boolean> = withContext(Dispatchers.IO) {
        return@withContext try {
            val token = fcmTokenManager.getFCMToken()

            if (token != null) {
                // TODO: Implementar la llamada real a la API
                // val response = apiService.registerFCMToken(
                //     FCMTokenRequest(
                //         token = token,
                //         userId = userId,
                //         deviceInfo = deviceInfo
                //     )
                // )

                Log.d(TAG, "Token registrado exitosamente: $token")
                Log.d(TAG, "Usuario: $userId")
                Log.d(TAG, "Info del dispositivo: $deviceInfo")

                // Simular respuesta exitosa por ahora
                Result.success(true)
            } else {
                Log.e(TAG, "No se pudo obtener el token FCM")
                Result.failure(Exception("No se pudo obtener el token FCM"))
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error al registrar token en el servidor", e)
            Result.failure(e)
        }
    }

    /**
     * Actualiza las preferencias de notificación del usuario en el servidor
     */
    suspend fun updateNotificationPreferences(
        userId: String,
        preferences: NotificationPreferences
    ): Result<Boolean> = withContext(Dispatchers.IO) {
        return@withContext try {
            // TODO: Implementar la llamada real a la API
            // val response = apiService.updateNotificationPreferences(
            //     userId,
            //     preferences
            // )

            Log.d(TAG, "Preferencias actualizadas para usuario: $userId")
            Log.d(TAG, "Preferencias: $preferences")

            // Suscribirse/desuscribirse de topics según las preferencias
            if (preferences.enablePromotions) {
                fcmTokenManager.subscribeToTopic("promotions") { success ->
                    Log.d(TAG, "Suscripción a promociones: $success")
                }
            } else {
                fcmTokenManager.unsubscribeFromTopic("promotions") { success ->
                    Log.d(TAG, "Desuscripción de promociones: $success")
                }
            }

            if (preferences.enableOrderUpdates) {
                fcmTokenManager.subscribeToTopic("order_updates") { success ->
                    Log.d(TAG, "Suscripción a actualizaciones de pedidos: $success")
                }
            } else {
                fcmTokenManager.unsubscribeFromTopic("order_updates") { success ->
                    Log.d(TAG, "Desuscripción de actualizaciones de pedidos: $success")
                }
            }

            Result.success(true)
        } catch (e: Exception) {
            Log.e(TAG, "Error al actualizar preferencias", e)
            Result.failure(e)
        }
    }

    /**
     * Desregistra el token del servidor (útil al cerrar sesión)
     */
    suspend fun unregisterTokenFromServer(userId: String? = null): Result<Boolean> = 
        withContext(Dispatchers.IO) {
            return@withContext try {
                val token = fcmTokenManager.getSavedToken()

                if (token != null) {
                    // TODO: Implementar la llamada real a la API
                    // val response = apiService.unregisterFCMToken(token, userId)

                    Log.d(TAG, "Token desregistrado del servidor: $token")

                    // Limpiar token local
                    fcmTokenManager.clearToken()

                    Result.success(true)
                } else {
                    Log.w(TAG, "No hay token para desregistrar")
                    Result.success(true)
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error al desregistrar token", e)
                Result.failure(e)
            }
        }

    /**
     * Obtiene el token actual
     */
    suspend fun getCurrentToken(): String? {
        return try {
            fcmTokenManager.getFCMToken()
        } catch (e: Exception) {
            Log.e(TAG, "Error al obtener token actual", e)
            null
        }
    }

    /**
     * Refresca el token FCM
     */
    suspend fun refreshToken(): Result<String> = withContext(Dispatchers.IO) {
        return@withContext try {
            val newToken = fcmTokenManager.refreshToken()
            if (newToken != null) {
                Result.success(newToken)
            } else {
                Result.failure(Exception("No se pudo refrescar el token"))
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error al refrescar token", e)
            Result.failure(e)
        }
    }
}

/**
 * Data class para las preferencias de notificación
 */
data class NotificationPreferences(
    val enablePromotions: Boolean = true,
    val enableOrderUpdates: Boolean = true,
    val enableReminders: Boolean = true,
    val enableGeneralNotifications: Boolean = true,
    val quietHoursStart: String? = null, // Formato "HH:mm"
    val quietHoursEnd: String? = null,   // Formato "HH:mm"
    val allowSound: Boolean = true,
    val allowVibration: Boolean = true
)

/**
 * Data class para el request de registro de token
 */
data class FCMTokenRequest(
    val token: String,
    val userId: String? = null,
    val deviceInfo: Map<String, String> = emptyMap(),
    val platform: String = "android"
)

package com.intellisoft.androidcuisine.domain.usecase

import com.intellisoft.androidcuisine.data.managers.FCMTokenManager
import com.intellisoft.androidcuisine.data.repository.FCMRepository
import com.intellisoft.androidcuisine.data.repository.NotificationPreferences
import javax.inject.Inject

/**
 * UseCase para manejar operaciones de notificaciones FCM
 */
class NotificationUseCase @Inject constructor(
    private val fcmRepository: FCMRepository,
    private val fcmTokenManager: FCMTokenManager
) {

    /**
     * Inicializa el sistema de notificaciones para un usuario
     */
    suspend fun initializeNotificationsForUser(
        userId: String,
        deviceInfo: Map<String, String> = emptyMap()
    ): Result<String> {
        return try {
            // Registrar token en el servidor
            val registerResult = fcmRepository.registerTokenWithServer(userId, deviceInfo)

            if (registerResult.isSuccess) {
                // Obtener el token actual
                val token = fcmRepository.getCurrentToken()
                if (token != null) {
                    Result.success(token)
                } else {
                    Result.failure(Exception("No se pudo obtener el token"))
                }
            } else {
                Result.failure(registerResult.exceptionOrNull() ?: Exception("Error al registrar token"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    /**
     * Actualiza las preferencias de notificación del usuario
     */
    suspend fun updateUserNotificationPreferences(
        userId: String,
        preferences: NotificationPreferences
    ): Result<Boolean> {
        return fcmRepository.updateNotificationPreferences(userId, preferences)
    }

    /**
     * Cierra sesión y limpia los tokens de notificación
     */
    suspend fun logoutAndClearNotifications(userId: String): Result<Boolean> {
        return fcmRepository.unregisterTokenFromServer(userId)
    }

    /**
     * Refresca el token FCM
     */
    suspend fun refreshNotificationToken(): Result<String> {
        return fcmRepository.refreshToken()
    }

    /**
     * Verifica si las notificaciones están habilitadas en el dispositivo
     */
    fun areNotificationsEnabled(): Boolean {
        return fcmTokenManager.areNotificationsEnabled()
    }

    /**
     * Obtiene el token actual sin hacer llamadas de red
     */
    fun getCurrentTokenSync(): String? {
        return fcmTokenManager.getSavedToken()
    }

    /**
     * Verifica si el token actual es válido
     */
    fun isTokenValid(): Boolean {
        return fcmTokenManager.isTokenValid()
    }

    /**
     * Suscribe al usuario a topics específicos
     */
    suspend fun subscribeToUserTopics(
        userId: String,
        userPreferences: NotificationPreferences
    ) {
        // Topic personalizado por usuario
        fcmTokenManager.subscribeToTopic("user_$userId") { success ->
            // Manejar resultado
        }

        // Topics basados en preferencias
        if (userPreferences.enablePromotions) {
            fcmTokenManager.subscribeToTopic("promotions") { success ->
                // Manejar resultado
            }
        }

        if (userPreferences.enableOrderUpdates) {
            fcmTokenManager.subscribeToTopic("order_updates") { success ->
                // Manejar resultado
            }
        }

        if (userPreferences.enableReminders) {
            fcmTokenManager.subscribeToTopic("reminders") { success ->
                // Manejar resultado
            }
        }
    }

    /**
     * Desuscribe al usuario de todos los topics
     */
    suspend fun unsubscribeFromAllTopics(userId: String) {
        val topics = listOf(
            "user_$userId",
            "promotions",
            "order_updates",
            "reminders",
            "all_users"
        )

        topics.forEach { topic ->
            fcmTokenManager.unsubscribeFromTopic(topic) { success ->
                // Manejar resultado individual si es necesario
            }
        }
    }
}

package com.intellisoft.androidcuisine.util

import android.content.Context
import android.util.Log
import com.intellisoft.androidcuisine.data.managers.FCMTokenManager
import com.intellisoft.androidcuisine.data.repository.FCMRepository
import com.intellisoft.androidcuisine.domain.usecase.NotificationUseCase
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

/**
 * Utilidad para probar la funcionalidad de FCM
 */
class FCMTestHelper(private val context: Context) {

    companion object {
        private const val TAG = "FCMTestHelper"
    }

    private val fcmTokenManager = FCMTokenManager(context)
    private val fcmRepository = FCMRepository(fcmTokenManager)
    private val notificationUseCase = NotificationUseCase(fcmRepository, fcmTokenManager)
    private val notificationHelper = NotificationHelper(context)

    /**
     * Ejecuta una serie de pruebas básicas del sistema FCM
     */
    fun runBasicTests() {
        Log.d(TAG, "=== Iniciando pruebas básicas de FCM ===")

        // Test 1: Verificar si las notificaciones están habilitadas
        testNotificationPermissions()

        // Test 2: Probar obtención de token
        testTokenGeneration()

        // Test 3: Probar notificaciones locales
        testLocalNotifications()

        // Test 4: Probar suscripciones a topics
        testTopicSubscriptions()

        Log.d(TAG, "=== Pruebas básicas completadas ===")
    }

    private fun testNotificationPermissions() {
        Log.d(TAG, "Test 1: Verificando permisos de notificación")
        val enabled = fcmTokenManager.areNotificationsEnabled()
        Log.d(TAG, "Notificaciones habilitadas: $enabled")

        if (!enabled) {
            Log.w(TAG, "⚠️ Las notificaciones no están habilitadas en el dispositivo")
        } else {
            Log.d(TAG, "✅ Permisos de notificación OK")
        }
    }

    private fun testTokenGeneration() {
        Log.d(TAG, "Test 2: Probando generación de token")

        CoroutineScope(Dispatchers.Main).launch {
            try {
                val token = fcmTokenManager.getFCMToken()
                if (token != null) {
                    Log.d(TAG, "✅ Token obtenido exitosamente")
                    Log.d(TAG, "Token: ${token.take(20)}...")
                } else {
                    Log.e(TAG, "❌ Error: No se pudo obtener el token")
                }
            } catch (e: Exception) {
                Log.e(TAG, "❌ Excepción al obtener token", e)
            }
        }
    }

    private fun testLocalNotifications() {
        Log.d(TAG, "Test 3: Probando notificaciones locales")

        try {
            // Probar notificación general
            notificationHelper.showGeneralNotification(
                title = "Test FCM",
                message = "Esta es una notificación de prueba general"
            )

            // Probar notificación de pedido
            notificationHelper.showOrderNotification(
                orderId = "TEST123",
                status = "En preparación",
                message = "Tu pedido de prueba está siendo preparado"
            )

            // Probar notificación de promoción
            notificationHelper.showPromotionNotification(
                title = "¡Oferta Especial!",
                message = "50% de descuento en tu próximo pedido",
                promoCode = "TEST50"
            )

            Log.d(TAG, "✅ Notificaciones locales enviadas")
        } catch (e: Exception) {
            Log.e(TAG, "❌ Error al enviar notificaciones locales", e)
        }
    }

    private fun testTopicSubscriptions() {
        Log.d(TAG, "Test 4: Probando suscripciones a topics")

        val testTopics = listOf("test_topic", "promotions_test")

        testTopics.forEach { topic ->
            fcmTokenManager.subscribeToTopic(topic) { success ->
                if (success) {
                    Log.d(TAG, "✅ Suscrito exitosamente a: $topic")
                } else {
                    Log.e(TAG, "❌ Error al suscribirse a: $topic")
                }
            }
        }
    }

    /**
     * Prueba la inicialización completa del sistema para un usuario
     */
    fun testUserInitialization(userId: String) {
        Log.d(TAG, "=== Probando inicialización para usuario: $userId ===")

        CoroutineScope(Dispatchers.Main).launch {
            try {
                val deviceInfo = mapOf(
                    "device_model" to android.os.Build.MODEL,
                    "android_version" to android.os.Build.VERSION.RELEASE,
                    "app_version" to getAppVersion()
                )

                val result = notificationUseCase.initializeNotificationsForUser(
                    userId = userId,
                    deviceInfo = deviceInfo
                )

                result.fold(
                    onSuccess = { token ->
                        Log.d(TAG, "✅ Inicialización exitosa para usuario $userId")
                        Log.d(TAG, "Token: ${token.take(20)}...")
                    },
                    onFailure = { error ->
                        Log.e(TAG, "❌ Error en inicialización para usuario $userId", error)
                    }
                )
            } catch (e: Exception) {
                Log.e(TAG, "❌ Excepción en inicialización", e)
            }
        }
    }

    /**
     * Simula la recepción de diferentes tipos de notificaciones
     */
    fun simulateNotificationTypes() {
        Log.d(TAG, "=== Simulando diferentes tipos de notificaciones ===")

        // Simular notificación de pedido
        simulateOrderNotification()

        // Simular notificación de promoción  
        simulatePromotionNotification()

        // Simular notificación de recordatorio
        simulateReminderNotification()
    }

    private fun simulateOrderNotification() {
        Log.d(TAG, "Simulando notificación de pedido...")

        notificationHelper.showOrderNotification(
            orderId = "ORD-2024-001",
            status = "Confirmado",
            message = "Tu pedido ha sido confirmado y será entregado en 30-45 minutos"
        )
    }

    private fun simulatePromotionNotification() {
        Log.d(TAG, "Simulando notificación de promoción...")

        notificationHelper.showPromotionNotification(
            title = "¡Descuento Especial!",
            message = "Obtén 25% de descuento en todos los platos principales hasta medianoche",
            promoCode = "PROMO25"
        )
    }

    private fun simulateReminderNotification() {
        Log.d(TAG, "Simulando notificación de recordatorio...")

        notificationHelper.showReminderNotification(
            title = "¿Tienes hambre?",
            message = "Es hora de almorzar. ¡Revisa nuestro menú del día!"
        )
    }

    /**
     * Obtiene la versión de la aplicación
     */
    private fun getAppVersion(): String {
        return try {
            val packageInfo = context.packageManager.getPackageInfo(context.packageName, 0)
            packageInfo.versionName ?: "Unknown"
        } catch (e: Exception) {
            "Unknown"
        }
    }

    /**
     * Limpia todas las notificaciones de prueba
     */
    fun cleanupTestNotifications() {
        Log.d(TAG, "Limpiando notificaciones de prueba...")
        notificationHelper.cancelAllNotifications()
        Log.d(TAG, "✅ Notificaciones limpiadas")
    }

    /**
     * Imprime el estado actual del sistema FCM
     */
    fun printSystemStatus() {
        Log.d(TAG, "=== Estado del Sistema FCM ===")
        Log.d(TAG, "Notificaciones habilitadas: ${fcmTokenManager.areNotificationsEnabled()}")
        Log.d(TAG, "Token válido: ${fcmTokenManager.isTokenValid()}")

        val savedToken = fcmTokenManager.getSavedToken()
        if (savedToken != null) {
            Log.d(TAG, "Token guardado: ${savedToken.take(20)}...")
        } else {
            Log.d(TAG, "No hay token guardado")
        }
        Log.d(TAG, "=============================")
    }
}

package com.intellisoft.androidcuisine.util

import android.Manifest
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import androidx.core.app.ActivityCompat
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import com.intellisoft.androidcuisine.CuisieneApp
import com.intellisoft.androidcuisine.R

/**
 * Utilidad simplificada para manejar notificaciones básicas
 */
class NotificationHelper(private val context: Context) {

    companion object {
        const val CHANNEL_ID = "cuisine_notifications"
        const val CHANNEL_NAME = "Cuisine Notifications"
    }

    private val notificationManager = NotificationManagerCompat.from(context)

    init {
        createNotificationChannel()
    }

    /**
     * Crea el canal de notificaciones
     */
    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val channel = NotificationChannel(
                CHANNEL_ID,
                CHANNEL_NAME,
                NotificationManager.IMPORTANCE_HIGH
            ).apply {
                description = "Notificaciones de la aplicación Cuisine"
                enableLights(true)
                enableVibration(true)
            }

            val systemNotificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) 
                as NotificationManager
            systemNotificationManager.createNotificationChannel(channel)
        }
    }

    /**
     * Muestra una notificación básica
     */
    fun showNotification(
        title: String,
        message: String,
        intent: Intent? = null
    ) {
        // Verificar permisos antes de mostrar notificación
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            if (ActivityCompat.checkSelfPermission(
                    context,
                    Manifest.permission.POST_NOTIFICATIONS
                ) != PackageManager.PERMISSION_GRANTED
            ) {
                return
            }
        }

        // Intent por defecto para abrir la app
        val defaultIntent = intent ?: Intent(context, CuisieneApp::class.java).apply {
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
        }

        val pendingIntent = PendingIntent.getActivity(
            context,
            System.currentTimeMillis().toInt(),
            defaultIntent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // Construir la notificación
        val notificationBuilder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_launcher_foreground)
            .setContentTitle(title)
            .setContentText(message)
            .setStyle(NotificationCompat.BigTextStyle().bigText(message))
            .setAutoCancel(true)
            .setContentIntent(pendingIntent)
            .setPriority(NotificationCompat.PRIORITY_HIGH)

        // Mostrar la notificación
        notificationManager.notify(System.currentTimeMillis().toInt(), notificationBuilder.build())
    }
}

